html:
{%- if doc.status not in ("Released", "Sold") -%}
<p>{{ _("This document can be printed only after the vehicle is released.") }}</p>
{%- else -%}
{%- set loan = frappe.get_doc("Loan", doc.current_loan) -%}
{%- set company = frappe.get_doc("Company", doc.hypothecated_to or loan.company) -%}
<p class="text-right">{{ _("Date") }}: {{ frappe.utils.formatdate(doc.noc_issued_on or frappe.utils.nowdate()) }}</p>
<p>{{ _("To") }},<br>{{ doc.applicant_name }}</p>
<h4 class="text-center">{{ _("No Objection Certificate") }}</h4>
<p>{{ _("Loan Account") }}: <b>{{ loan.name }}</b></p>
{%- if loan.status == "Settled" -%}
<p>{{ _("The above loan has been settled. {0} has no objection to the termination of the hypothecation on the vehicle below.").format(company.company_name) }}</p>
{%- else -%}
<p>{{ _("The above loan has been repaid in full and closed. {0} has no objection to the termination of the hypothecation on the vehicle below.").format(company.company_name) }}</p>
{%- endif -%}
<table class="table table-bordered">
	<tr><td>{{ _("Registration Number") }}</td><td>{{ doc.registration_number or "" }}</td></tr>
	<tr><td>{{ _("Chassis Number") }}</td><td>{{ doc.chassis_number or "" }}</td></tr>
	<tr><td>{{ _("Engine Number") }}</td><td>{{ doc.engine_number or "" }}</td></tr>
	<tr><td>{{ _("Make and Model") }}</td><td>{{ doc.vehicle_model }}</td></tr>
	<tr><td>{{ _("Registered Owner") }}</td><td>{{ doc.rc_owner_name or doc.applicant_name }}</td></tr>
</table>
<p>{{ _("Please submit Form 35 with this certificate at the registering authority within 90 days.") }}</p>
<p style="margin-top: 60px">{{ _("For") }} {{ company.company_name }}<br><br>{{ _("Authorised Signatory") }}</p>
{%- endif -%}
